import subprocess, itertools
seqs={}; name=None
for line in open('sequences.fasta'):
    line=line.strip()
    if line.startswith('>'): name=line[1:]; seqs[name]=[]
    else: seqs[name].append(line)
S={k:''.join(v).lower() for k,v in seqs.items()}
inp,e,f,snap=S['input'],S['egfp'],S['flag'],S['snap']
rc=lambda x:x.translate(str.maketrans('acgt','tgca'))[::-1]
def tm(x):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',x],capture_output=True,text=True)
    return float(r.stdout.strip())
def regions(sidx):
    q=210+sidx
    return {
      'input_fwd': inp[694:694+60],
      'input_rev': rc(inp[q-60:q]),
      'egfp_fwd': e[sidx+4:sidx+4+60],
      'egfp_rev': rc(e[len(e)-3-60:len(e)-3]),
      'flag_fwd': f[7:7+60],
      'flag_rev': rc(f[len(f)-3-60:len(f)-3]),
      'snap_fwd': snap[7:7+60],
      'snap_rev': rc(snap[len(snap)-60:]),
    }
for sidx in range(5):
    print('=== s',sidx,'overhang',e[sidx:sidx+4],'rc',rc(e[sidx:sidx+4]))
    regs=regions(sidx)
    valid={}
    for k,seq in regs.items():
        vals=[]
        for L in range(15,37):
            t=tm(seq[:L])
            if 58<=t<=72: vals.append((L,round(t,2)))
        valid[k]=dict(vals)
        # print compact ranges
        print(' ',k,'valid lengths:',[L for L in valid[k]])
    for fw,rv in [('input_fwd','input_rev'),('egfp_fwd','egfp_rev'),('flag_fwd','flag_rev'),('snap_fwd','snap_rev')]:
        pairs=[]
        for L1,t1 in valid[fw].items():
            for L2,t2 in valid[rv].items():
                if abs(t1-t2)<=5:
                    pairs.append((L1,L2,round(t1,2),round(t2,2),round(abs(t1-t2),2)))
        # choose minimal total length, then min diff
        pairs.sort(key=lambda x:(x[0]+x[1],x[4]))
        print('   pair',fw,rv,'best:',pairs[:5],'count',len(pairs))
EOF
